<?php
declare(strict_types=1);namespace App\Http\Controllers\TeachingAssignments;use App\Http\Controllers\Controller;use App\Models\{TeachingAssignmentException,TeachingAssignmentSet};use Illuminate\Http\{RedirectResponse,Request};
class TeachingAssignmentExceptionController extends Controller {public function store(Request $r,TeachingAssignmentSet $set):RedirectResponse{abort_unless($r->user()->can('teaching-assignments.update'),403);abort_unless($set->isEditable(),422);$data=$r->validate(['classroom_id'=>'required|exists:classrooms,id','subject_id'=>'required|exists:subjects,id','reason'=>'required|string|min:10|max:1000']);TeachingAssignmentException::updateOrCreate(['assignment_set_id'=>$set->id,'classroom_id'=>$data['classroom_id'],'subject_id'=>$data['subject_id']],['reason'=>$data['reason'],'created_by'=>$r->user()->id]);return back()->with('success','Alasan pengecualian berhasil disimpan.');}}
